#include <iostream>
#include <sstream>
#include <string>
#include <iomanip>
#include <cstdlib>

// Demonstrates sequential record validation and stream boolean testing
// using standard C++17 streams (simulated via std::stringstream in sandbox)
int main() {
    // Simulate input stream from user terminal with EOF
    std::string testData = "100 Jones 24.98\n200 Doe 345.67\n300 White 0.00\n";
    std::istringstream inputSimulation(testData);

    // Verify stream readiness using explicit operator bool
    if (!inputSimulation) {
        std::cerr << "File could not be opened" << std::endl;
        return EXIT_FAILURE;
    }

    // Target stream to buffer written sequential records
    std::ostringstream recordBuffer;

    // Configure floating point formatting to match original text format
    recordBuffer << std::fixed << std::setprecision(2);

    int account;
    std::string name;
    double balance;

    // Sequential extraction loop equivalent to: while (cin >> account >> name >> balance)
    while (inputSimulation >> account >> name >> balance) {
        recordBuffer << account << ' ' << name << ' ' << balance << '\n';
    }

    std::cout << "Recorded sequential data successfully:\n";
    std::cout << recordBuffer.str();

    return EXIT_SUCCESS;
}

#include <iostream>
#include <iomanip>
#include <string>
#include <sstream>
#include <cstdlib>

// Formats and displays a single account record (equivalent to Fig 14.6 outputLine)
void outputLine(int account, const std::string& name, double balance) {
    std::cout << std::left << std::setw(10) << account
              << std::setw(13) << name
              << std::setw(7) << std::setprecision(2) << std::right << balance
              << std::endl;
}

int main() {
    // Simulated sequential file content based on Fig 14.6
    std::string fileContent =
        "100 Jones 24.98\n"
        "200 Doe 345.67\n"
        "300 White 0.00\n"
        "400 Stone -42.16\n"
        "500 Rich 224.62\n";

    std::istringstream inClientFile(fileContent);

    if (!inClientFile) {
        std::cerr << "File could not be opened" << std::endl;
        return EXIT_FAILURE;
    }

    int account;
    std::string name;
    double balance;

    // Table header
    std::cout << std::left << std::setw(10) << "Account"
              << std::setw(13) << "Name"
              << "Balance" << std::endl
              << std::fixed << std::showpoint;

    // Read each record sequentially until EOF
    while (inClientFile >> account >> name >> balance) {
        outputLine(account, name, balance);
    }

    return EXIT_SUCCESS;
}
